exact_pair_schedule_and_deadline_check:
let same_pairs = incoming_pairs(&sep.layout, &incoming_keys);
let mixed_pairs = mixed_incoming_pairs(&sep.layout, &incoming_keys);
let mut choices =
    Vec::with_capacity(same_pairs.len() + mixed_pairs.len() + incoming_keys.len());
for index in 0..same_pairs.len().max(mixed_pairs.len()) {
    if let Some(pair) = same_pairs.get(index) {
        choices.push(pair.clone());
    }
    if let Some(pair) = mixed_pairs.get(index) {
        choices.push(pair.clone());
    }
}
choices.extend(incoming_keys.into_iter().map(|key| vec![key]));
for selected in choices {
    let paired = selected.len() == 2;
    let exchange_until = if paired { group_until } else { until };
    if self.clock.now() >= self.last_step(exchange_until) {
        continue;
    }

exact_post_validation_neutral_guard:
// Same inventory can still improve the geometry, but a
// flat material result must not consume the sole exchange.
if same_original_inventory(&members, &victims)
    && after.material_area >= before.material_area
{
    self.stats.neutral_exchange_rejections += 1;
    continue;
}
